  "Compared against": "Compared against",
  "Compares your actual routed spend with the estimated cost of using only the most expensive model configured in the auto-router. It accounts for both the cache savings from staying on one model and the added cache costs from switching models. Savings are net of recorded LLM classification cost, which is included in actual spend. Classification cost per 1K turns is averaged over all auto-router turns, including those that skip classification. The range counts whole sessions that overlap it, so totals can differ slightly from the Overall tab, which buckets savings by UTC day.": "Compares your actual routed spend with the estimated cost of using only the most expensive model configured in the auto-router. It accounts for both the cache savings from staying on one model and the added cache costs from switching models. Savings are net of recorded LLM classification cost, which is included in actual spend. Classification cost per 1K turns is averaged over all auto-router turns, including those that skip classification. The range counts whole sessions that overlap it, so totals can differ slightly from the Overall tab, which buckets savings by UTC day.",
  "Comparison only. This source request was not appended to the classifier input.": "Comparison only. This source request was not appended to the classifier input.",
