  "When on, LiteLLM skips its own API key/SSO check for this server and lets the client complete PKCE directly with the upstream MCP server. Only honored when Auth Type is oauth2. No spend tracking or per-key rate limiting will run on this route.": "When on, LiteLLM skips its own API key/SSO check for this server and lets the client complete PKCE directly with the upstream MCP server. Only honored when Auth Type is oauth2. No spend tracking or per-key rate limiting will run on this route.",
  "When on, only requests from within your internal network are accepted. Turn off to allow external clients (other clusters, ChatGPT, etc). API key authentication is always required regardless of this setting.": "When on, only requests from within your internal network are accepted. Turn off to allow external clients (other clusters, ChatGPT, etc). API key authentication is always required regardless of this setting.",
  "When on, this server is treated as an OAuth pass-through: the gateway proxies the upstream /.well-known/oauth-protected-resource metadata, emits spec-compliant 401 challenges when no bearer is supplied, and propagates upstream 401/403 responses. Only honored when Auth Type is None and 'Authorization' is in Extra Headers.": "When on, this server is treated as an OAuth pass-through: the gateway proxies the upstream /.well-known/oauth-protected-resource metadata, emits spec-compliant 401 challenges when no bearer is supplied, and propagates upstream 401/403 responses. Only honored when Auth Type is None and 'Authorization' is in Extra Headers.",
  "When rotation occurs, you'll receive a notification with the new key. The old key will be deactivated after a brief grace period.": "When rotation occurs, you'll receive a notification with the new key. The old key will be deactivated after a brief grace period.",
  "When the model keeps repeating the same tool call, or the same call keeps erroring, bump the request one tier higher for as long as it looks stuck. The automatic counterpart to an escalation keyword: nobody has to notice the loop and ask. Off means a stuck task keeps the model it was classified onto. {value0}": "When the model keeps repeating the same tool call, or the same call keeps erroring, bump the request one tier higher for as long as it looks stuck. The automatic counterpart to an escalation keyword: nobody has to notice the loop and ask. Off means a stuck task keeps the model it was classified onto. {value0}",
